mapper.select:
SELECT U.USER_ID, U.USER_NM, U.DEPT_ID, D.DEPT_NM, U.AUTH_CD, A.AUTH_NM, U.EMAIL, U.TEL_NO, U.USE_YN, U.LAST_LOGIN_DT FROM TB_USER U LEFT OUTER JOIN TB_DEPT D ON D.DEPT_ID = U.DEPT_ID LEFT OUTER JOIN TB_AUTH A ON A.AUTH_CD = U.AUTH_CD
U.DEPT_ID = #{deptId}
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND U.AUTH_CD = #{authCd}
ORDER BY D.DEPT_NM, U.USER_NM

mapper.update:
UPDATE TB_USER
   SET LAST_LOGIN_DT = NOW()
 WHERE USER_ID = #{userId}

UPDATE TB_USER
USER_NM = #{userNm}, DEPT_ID = #{deptId}, AUTH_CD = #{authCd}, EMAIL = #{email}, TEL_NO = #{telNo}, USE_YN = #{useYn}, PASSWD = SHA2(#{passwd}, 256), USER_ID = USER_ID
WHERE USER_ID = #{userId}
